mapper.sql:
, monthly_profit AS ( SELECT dimension_id, MAX(dimension_name) AS dimension_name, SUM(revenue_amount) AS revenue_amount, SUM(sales_cost_amount) AS sales_cost_amount, SUM(gift_cost_amount) AS gift_cost_amount, SUM(cost_missing_count) AS cost_missing_count FROM facts GROUP BY dimension_id ), monthly_expenses AS ( SELECT expense.customer_id, SUM(expense.tax_amount) AS tax_amount, SUM(expense.service_amount) AS service_amount, SUM(expense.freight_amount) AS freight_amount, SUM(expense.commission_amount) AS commission_amount FROM xsy_finance_customer_expense expense WHERE expense.expense_month = #{query.startDate} AND NOT EXISTS (SELECT 1 FROM xsy_finance_customer_expense_void v WHERE v.expense_id = expense.id) GROUP BY expense.customer_id ), monthly_base AS ( SELECT c.id AS dimension_id, COALESCE(p.dimension_name, c.name) AS dimension_name, COALESCE(p.revenue_amount, 0) AS revenue_amount, COALESCE(p.sales_cost_amount, 0) AS sales_cost_amount, COALESCE(p.gift_cost_amount, 0) AS gift_cost_amount, COALESCE(p.cost_missing_count, 0) AS cost_missing_count, COALESCE(e.tax_amount, 0) AS tax_amount, COALESCE(e.service_amount, 0) AS service_amount, COALESCE(e.freight_amount, 0) AS freight_amount, COALESCE(e.commission_amount, 0) AS commission_amount FROM monthly_profit p FULL JOIN monthly_expenses e ON e.customer_id = p.dimension_id JOIN xsy_customer c ON c.id = COALESCE(p.dimension_id, e.customer_id) AND c.deleted = FALSE WHERE TRUE
AND c.seller_id IN #{id}
AND FALSE
AND c.seller_id IN #{id}
AND FALSE
AND c.id = #{query.customerId} AND c.name ILIKE CONCAT('%', #{query.keyword}, '%') UNION ALL SELECT p.dimension_id, p.dimension_name, p.revenue_amount, p.sales_cost_amount, p.gift_cost_amount, p.cost_missing_count, 0::NUMERIC, 0::NUMERIC, 0::NUMERIC, 0::NUMERIC FROM monthly_profit p WHERE p.dimension_id IS NULL ), monthly_rows AS ( SELECT *, tax_amount + service_amount + freight_amount + commission_amount AS expense_amount, CASE WHEN cost_missing_count > 0 THEN NULL ELSE revenue_amount - sales_cost_amount - gift_cost_amount END AS gross_profit, CASE WHEN cost_missing_count > 0 THEN NULL ELSE revenue_amount - sales_cost_amount - gift_cost_amount - tax_amount - service_amount - freight_amount - commission_amount END AS net_profit FROM monthly_base )
